@CategoryID_0a30949527b8 UNIQUEIDENTIFIER,
@UserQuestion_0a30949527b8 NVARCHAR(MAX),
@Description_0a30949527b8 NVARCHAR(MAX),
@SQL_0a30949527b8 NVARCHAR(MAX),
@TechnicalDescription_0a30949527b8 NVARCHAR(MAX),
@OriginalSQL_0a30949527b8 NVARCHAR(MAX),
@Feedback_0a30949527b8 NVARCHAR(MAX),
@Status_0a30949527b8 NVARCHAR(15),
@QualityRank_0a30949527b8 INT,
@ExecutionCostRank_0a30949527b8 INT,
@UsesTemplate_0a30949527b8 BIT,
@AuditQueryRuns_0a30949527b8 BIT,
